        setIsLoading(true);

        setTimeout(() => {
            setIsLoading(false);
        }, 3000);
    }

    return (
        <>
            <div className="px-4 py-10 w-full grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 gap-6">
                <LoaderButton
                    buttonVariant={"default"}
                    onClick={onSubmit}
                    isLoading={isLoading}
                    className="my-class"
                >
                    Loader Button
                </LoaderButton>
                <LoaderButton
                    buttonVariant={"outline"}
                    onClick={onSubmit}
                    isLoading={isLoading}
                    className="my-class"
                >
                    Loader Button
                </LoaderButton>
                <LoaderButton
                    buttonVariant={"secondary"}
                    onClick={onSubmit}
                    isLoading={isLoading}
                    className="my-class"
                >
                    Loader Button
                </LoaderButton>
                <LoaderButton
                    buttonVariant={"ghost"}
                    onClick={onSubmit}
                    isLoading={isLoading}
                    className="my-class"
                >
                    Loader Button
